package dev.sablelife.testing;

import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import dev.sablelife.SableLife;
import dev.sablelife.heart.HeartBlockEntity;
import dev.sablelife.module.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.*;
import net.neoforged.neoforge.gametest.*;
import java.util.*;

@GameTestHolder("sablelife_melee_protection_tests") @PrefixGameTestTemplate(false)
public final class MeleeProtectionAndSwitchGameTests {
 static HeartBlockEntity fixture(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,50,4));l.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());l.setBlockAndUpdate(p.east(),Blocks.IRON_BLOCK.defaultBlockState());l.setBlockAndUpdate(p.west(),Blocks.IRON_BLOCK.defaultBlockState());l.setBlockAndUpdate(p.east(2),Blocks.REDSTONE_LAMP.defaultBlockState());l.setBlockAndUpdate(p.west(2),Blocks.REDSTONE_LAMP.defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p,p.east(),p.west(),p.east(2),p.west(2)),new BoundingBox3i(p.getX()-2,p.getY(),p.getZ(),p.getX()+2,p.getY(),p.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());var hover=c.modules().add("hover_anchor");hover.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.UP)));return c;}
 @GameTest(template="combat",batch="melee_own_list")
 public static void IndependentListsDoNotChangeCoreOrOtherMelee(GameTestHelper h){var c=fixture(h);var a=c.modules().add("melee");var b=c.modules().add("melee");c.terrainSettings().edit("crushProtectAdd",0,"minecraft:stone");h.assertTrue(!a.meleeProtection(c).protects(Blocks.STONE.defaultBlockState()),"New module inherited core list");a.meleeProtection(c).edit("crushProtectAdd",0,"#minecraft:flowers");h.assertTrue(a.meleeProtection().protects(Blocks.DANDELION.defaultBlockState())&&!b.meleeProtection(c).protects(Blocks.DANDELION.defaultBlockState())&&!c.terrainSettings().protects(Blocks.DANDELION.defaultBlockState()),"Melee lists leaked");var copied=ModulePreset.create(a.save());h.assertTrue(copied.meleeProtection().protects(Blocks.POPPY.defaultBlockState()),"Preset dropped own list");h.succeed();}
 @GameTest(template="combat",batch="melee_legacy_list")
 public static void Old445CopiesCoreListOnceAndPersistsIndependently(GameTestHelper h){var c=fixture(h);c.terrainSettings().edit("crushProtectAdd",0,"minecraft:stone");var m=new VirtualModule("melee");m.edit("meleeBreakBlocks",1,"");var old=m.save();old.remove("MeleeProtection");var loaded=VirtualModule.load(old);h.assertTrue(!loaded.save().contains("MeleeProtection"),"Unresolved legacy list was silently erased");h.assertTrue(loaded.meleeProtection(c).protects(Blocks.STONE.defaultBlockState()),"445 protection lost during migration");c.terrainSettings().edit("crushProtectAdd",0,"minecraft:dirt");h.assertTrue(!loaded.meleeProtection(c).protects(Blocks.DIRT.defaultBlockState()),"Migrated list still follows core");var saved=VirtualModule.load(loaded.save());h.assertTrue(saved.meleeProtection(c).entries().equals(List.of("minecraft:stone")),"Migration was not idempotent");h.succeed();}
 @GameTest(template="combat",batch="melee_missing_decor")
 public static void MissingDecorationIdsSurviveReloadAndListIsBounded(GameTestHelper h){var tag=new net.minecraft.nbt.CompoundTag();var list=new net.minecraft.nbt.ListTag();list.add(net.minecraft.nbt.StringTag.valueOf("absent_decoration:flower"));tag.put("Protected",list);var p=new MeleeBlockProtection();p.load(tag);var again=new MeleeBlockProtection();again.load(p.save());h.assertTrue(again.entries().equals(List.of("absent_decoration:flower")),"Missing optional block ID was erased");for(int i=0;i<127;i++)h.assertTrue(again.edit("crushProtectAdd",0,"#test:tag_"+i),"Entry below cap rejected");h.assertTrue(!again.edit("crushProtectAdd",0,"#test:over_limit")&&again.entries().size()==128,"128-entry cap bypassed");h.succeed();}
 @GameTest(template="combat",batch="melee_list_network")
 public static void ActualCodecAndMenuEnforcePermissionsRevisionAndBounds(GameTestHelper h){var c=fixture(h);var m=c.modules().add("melee");var p=TestActors.creative(h.getLevel());p.setPos(ModuleArena.corePosition(c));var menu=new HeartDashboardMenu(6,p.getInventory(),c);String longest="#minecraft:"+"a".repeat(69);h.assertTrue(longest.length()==80,"Bad fixture length");var a=new ModuleNetworking.Action(6,c.modules().revision(),m.id(),"melee_protect","crushProtectAdd",0,longest);var buf=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{ModuleNetworking.Action.CODEC.encode(buf,a);h.assertTrue(ModuleNetworking.Action.CODEC.decode(buf).equals(a),"80-char list entry codec lost data");}finally{buf.release();}h.assertTrue(menu.action(p,a.revision(),m.id(),a.operation(),a.key(),0,a.text()),"Normal menu rejected list entry");h.assertTrue(!menu.action(p,a.revision(),m.id(),a.operation(),a.key(),0,"minecraft:stone"),"Stale request accepted");var denied=TestActors.creative(h.getLevel());denied.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);denied.setPos(p.position());h.assertTrue(!menu.action(denied,c.modules().revision(),m.id(),a.operation(),a.key(),0,"minecraft:stone"),"Ordinary survival player edited list");h.assertTrue(!m.meleeProtection().edit("crushProtectAdd",0,longest+"a"),"Oversize entry accepted");var tooLong=new ModuleNetworking.Action(6,0,m.id(),a.operation(),a.key(),0,longest+"a");var oversized=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());boolean rejected=false;try{ModuleNetworking.Action.CODEC.encode(oversized,tooLong);}catch(io.netty.handler.codec.EncoderException expected){rejected=true;}finally{oversized.release();}h.assertTrue(rejected,"81-char packet encoded");h.succeed();}
 @GameTest(template="combat",batch="face_switch",timeoutTicks=245)
 public static void MoveSetRightThenLeftFiveSecondsUpdatesActualLamps(GameTestHelper h){var c=fixture(h);var root=c.getBlockPos();var l=h.getLevel();var a=c.modules().add("wireless_redstone");a.anchors(List.of(ModuleAnchor.create(c,root.east(2),Direction.WEST)));a.edit("redstoneFaces",1,"");a.edit("trigger",4,"");var b=c.modules().add("wireless_redstone");b.anchors(List.of(ModuleAnchor.create(c,root.west(2),Direction.EAST)));b.edit("redstoneFaces",1,"");b.edit("trigger",4,"");h.assertTrue(l.getBlockState(root.east(2)).is(Blocks.REDSTONE_LAMP)&&l.getBlockState(root.west(2)).is(Blocks.REDSTONE_LAMP),"Fixture lost owned lamps after assembly");var table=c.modules().add("move_set");table.edit("ignoreConditions",1,"");table.moveSet().edit("add",0,"",c.modules());table.moveSet().edit("action_add",0,"0|"+a.id(),c.modules());table.moveSet().edit("action_duration",5,"0|0",c.modules());table.moveSet().edit("action_add",0,"0|"+b.id(),c.modules());table.moveSet().edit("action_start",5,"0|1",c.modules());table.moveSet().edit("action_duration",5,"0|1",c.modules());table.moveSet().edit("dispatchCooldown",500,"0",c.modules());c.tryActivate(TestActors.creative(l));c.modules().tick(c);
  h.runAfterDelay(5,()->{h.assertTrue(l.getBlockState(root.east(2)).getValue(RedstoneLampBlock.LIT)&&!l.getBlockState(root.west(2)).getValue(RedstoneLampBlock.LIT),"First face did not update real lamps");});
  h.runAfterDelay(110,()->{h.assertTrue(!l.getBlockState(root.east(2)).getValue(RedstoneLampBlock.LIT)&&l.getBlockState(root.west(2)).getValue(RedstoneLampBlock.LIT),"Second face was swallowed or first remained On");});
  h.runAfterDelay(210,()->{h.assertTrue(!l.getBlockState(root.east(2)).getValue(RedstoneLampBlock.LIT)&&!l.getBlockState(root.west(2)).getValue(RedstoneLampBlock.LIT),"Ended move retained face output");h.succeed();});
 }
 @GameTest(template="combat",batch="fast_face_switch",timeoutTicks=65)
 public static void SixteenConsecutiveOneTickActionsPublishBothFacesWithoutStalePower(GameTestHelper h){var c=fixture(h);var root=c.getBlockPos();var a=c.modules().add("wireless_redstone");a.anchors(List.of(ModuleAnchor.create(c,root.east(2),Direction.WEST)));a.edit("redstoneFaces",1,"");a.edit("trigger",4,"");var b=c.modules().add("wireless_redstone");b.anchors(List.of(ModuleAnchor.create(c,root.west(2),Direction.EAST)));b.edit("redstoneFaces",1,"");b.edit("trigger",4,"");var table=c.modules().add("move_set");table.edit("ignoreConditions",1,"");table.moveSet().edit("add",0,"",c.modules());for(int n=0;n<16;n++){h.assertTrue(table.moveSet().edit("action_add",0,"0|"+(n%2==0?a:b).id(),c.modules()),"Rapid action fixture exceeded supported limit");table.moveSet().edit("action_start",n/20.0,"0|"+n,c.modules());table.moveSet().edit("action_duration",.05,"0|"+n,c.modules());}table.moveSet().edit("dispatchCooldown",500,"0",c.modules());c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);for(int n=1;n<16;n++){final int step=n;h.runAfterDelay(n,()->{c.modules().tick(c);int right=h.getLevel().getBestNeighborSignal(root.east(2)),left=h.getLevel().getBestNeighborSignal(root.west(2));h.assertTrue(right==(step%2==0?15:0)&&left==(step%2==0?0:15),"Stale or swallowed face signal at one-tick step "+step+": "+right+"/"+left);});}h.runAfterDelay(21,()->{c.modules().tick(c);h.assertTrue(h.getLevel().getBestNeighborSignal(root.east(2))==0&&h.getLevel().getBestNeighborSignal(root.west(2))==0,"Finished rapid actions left power");h.succeed();});}

 @GameTest(template="combat",batch="melee_options")
 public static void MeleeOptionsAreIndependentAndLast(GameTestHelper h){var c=fixture(h);var a=c.modules().add("melee");var b=c.modules().add("melee");c.terrainSettings().edit("crushDrops",1,"");c.terrainSettings().edit("crushDebris",1,"");h.assertTrue(a.value("meleeDrops")==0&&a.value("meleeDebris")==0,"New options not Off");a.edit("meleeDrops",1,"");a.edit("meleeDebris",1,"");h.assertTrue(b.value("meleeDrops")==0&&b.value("meleeDebris")==0,"Options leaked to another module");for(var key:List.of("meleeDrops","meleeDebris")){h.assertTrue(!a.edit(key,1.5,"")&&!a.edit(key,-1,"")&&!a.edit(key,2,""),"Invalid boolean accepted");h.assertTrue(VirtualModule.load(a.save()).value(key)==1&&ModulePreset.create(a.save()).value(key)==1,"Setting lost in save/preset");}var fields=ModuleFields.forType("melee").stream().map(ModuleFields.Field::key).toList();h.assertTrue(fields.subList(fields.size()-4,fields.size()).equals(List.of("meleeBreakBlocks","meleeProtected","meleeDebris","meleeDrops")),"Breaking controls not last");h.succeed();}
 @GameTest(template="combat",batch="melee_legacy_options")
 public static void LegacyMeleePreservesCoreDropsOnce(GameTestHelper h){var c=fixture(h);c.terrainSettings().edit("crushDrops",1,"");var old=new VirtualModule("melee").save();old.getCompound("Settings").remove("meleeDrops");old.getCompound("Settings").remove("meleeDebris");var m=VirtualModule.load(old);h.assertTrue(!m.save().getCompound("Settings").contains("meleeDrops"),"Unresolved legacy drop setting overwritten");m=VirtualModule.load(m.save());m.meleeProtection(c);h.assertTrue(m.value("meleeDrops")==1&&m.value("meleeDebris")==0,"Old drop/debris behavior changed");c.terrainSettings().edit("crushDrops",0,"");m.meleeProtection(c);var copy=VirtualModule.load(m.save());copy.meleeProtection(c);h.assertTrue(copy.value("meleeDrops")==1,"Migration repeated against changed core");h.succeed();}
 @GameTest(template="combat",batch="melee_inventory_options")
 public static void InventoryBatchUsesRealSlotsWithoutConsumption(GameTestHelper h){var c=fixture(h);var a=c.modules().add("melee");var b=c.modules().add("melee");var p=TestActors.creative(h.getLevel());p.setPos(ModuleArena.corePosition(c));for(int i=9;i<36;i++)p.getInventory().setItem(i,new net.minecraft.world.item.ItemStack(i%2==0?net.minecraft.world.item.Items.DIAMOND_BLOCK:net.minecraft.world.item.Items.EMERALD_BLOCK,12));var menu=new HeartDashboardMenu(17,p.getInventory(),c);String slots=java.util.stream.IntStream.range(9,36).mapToObj(i->String.format(java.util.Locale.ROOT,"%02d",i)).collect(java.util.stream.Collectors.joining(","));h.assertTrue(slots.length()==80,"Boundary fixture changed");var action=new ModuleNetworking.Action(17,c.modules().revision(),a.id(),"melee_protect","crushInvAdd",0,slots);var buf=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{ModuleNetworking.Action.CODEC.encode(buf,action);h.assertTrue(ModuleNetworking.Action.CODEC.decode(buf).equals(action),"Batch codec changed");}finally{buf.release();}var oversized=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());boolean rejected=false;try{ModuleNetworking.Action.CODEC.encode(oversized,new ModuleNetworking.Action(17,action.revision(),a.id(),action.operation(),action.key(),0,slots+","));}catch(io.netty.handler.codec.EncoderException expected){rejected=true;}finally{oversized.release();}h.assertTrue(rejected,"81-character batch was encoded");h.assertTrue(menu.action(p,action.revision(),a.id(),action.operation(),action.key(),0,slots),"Inventory batch rejected");h.assertTrue(a.meleeProtection().entries().size()==2&&b.meleeProtection().entries().isEmpty()&&c.terrainSettings().entries().isEmpty(),"Batch changed wrong protection list");h.assertTrue(p.getInventory().getItem(9).getCount()==12&&p.getInventory().getItem(35).getCount()==12,"Samples consumed inventory");h.assertTrue(!menu.action(p,action.revision(),a.id(),action.operation(),action.key(),0,slots),"Repeated stale batch accepted");for(String invalid:List.of("36","-1","9,9","9,","99","a","1,".repeat(41)))h.assertTrue(!menu.action(p,c.modules().revision(),a.id(),action.operation(),action.key(),0,invalid),"Malformed slots accepted: "+invalid);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);h.assertTrue(!menu.action(p,c.modules().revision(),a.id(),action.operation(),action.key(),0,"9"),"Unauthorized batch accepted");h.succeed();}
}
